sp_widget.client_script:
function($scope, $rootScope, $timeout) {

    var chartInstanceLinha = null;

    $scope.anoSelecionadoLinha = "";
    $scope.bimestreSelecionadoLinha = "";
    $scope.exibirGraficoLinha = false;

    function formatarNumero(valor) {
        if (typeof valor !== 'number') {
            valor = parseFloat(valor);
        }
        return valor.toFixed(2)
                    .replace('.', ',')
                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    }

    function carregarDadosDoServer() {
        var filtros = {
            ano: $scope.anoSelecionadoLinha || "",
            bimestre: $scope.bimestreSelecionadoLinha || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var listaDados = response.data.dadosGraficoLinha || [];
            $timeout(function() {
                inicializarGrafico(listaDados);
            }, 300); // delay de 300ms
        });
    }

    $rootScope.$on('filtroAnoSelecionado', function(event, ano) {
        $scope.anoSelecionadoLinha = ano;
        carregarDadosDoServer();
    });

    $rootScope.$on('filtroBimestreSelecionado', function(event, bimestre) {
        $scope.bimestreSelecionadoLinha = bimestre;
        carregarDadosDoServer();
    });

    carregarDadosDoServer();

    function inicializarGrafico(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartInstanceLinha) {
                chartInstanceLinha.destroy();
                chartInstanceLinha = null;
            }
            $scope.exibirGraficoLinha = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoLinha = true;
        $scope.$applyAsync();

        var labels = [];
        var resultadoData = [];

        for (var i = 0; i < listaDados.length; i++) {
            labels.push(listaDados[i].ano);
            resultadoData.push(listaDados[i].resultado);
        }

        var contexto = document.getElementById('graficoResultadoLinhaPrimario').getContext('2d');

        if (chartInstanceLinha) {
            chartInstanceLinha.destroy();
        }

        chartInstanceLinha = new Chart(contexto, {
            type: 'line',
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Resultado Primário',
                        data: resultadoData,
                        backgroundColor: '#6BB7F0',
                        borderColor: '#6BB7F0',
                        borderWidth: 2,
                        tension: 0.3,
                        pointBackgroundColor: 'rgba(107, 183, 240, 1)',
                        pointRadius: 5,
                        fill: false
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        },
                        offset: true
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valor em R$'
                        },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + formatarNumero(value);
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + formatarNumero(context.parsed.y);
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};

    function formatarNumero(valor) {
        if (typeof valor !== 'number') {
            valor = parseFloat(valor);
        }
        return valor.toFixed(2)
                    .replace('.', ',')
                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    }

    var anoFiltro = input.ano || "";
    var bimestreFiltro = input.bimestre || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_resultado_primario');
    gr.addQuery('u_rpps', true);

    if (anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }

    if (bimestreFiltro !== "") {
        gr.addQuery('u_bimestre', bimestreFiltro);
    }

    gr.query();

    var dadosAgrupados = {};
    while (gr.next()) {
        var ano = gr.getValue('u_ano');
        var bimestre = gr.getValue('u_bimestre');
        var rawValor = gr.getValue('u_resultado_primario') || "0";
        //var valorSemPontuacao = rawValor.trim().replace(/\./g, '').replace(',', '.');
        var resultado = parseFloat(rawValor) || 0;

        if (bimestreFiltro !== "") {
            var chave = ano + '-' + bimestre;
            if (!dadosAgrupados[chave]) {
                dadosAgrupados[chave] = {
                    ano: ano,
                    bimestre: bimestre,
                    resultado: 0,
                    resultadoFormatado: ''
                };
            }
            dadosAgrupados[chave].resultado += resultado;
            dadosAgrupados[chave].resultadoFormatado = formatarNumero(dadosAgrupados[chave].resultado);
        } else {
            if (!dadosAgrupados[ano]) {
                dadosAgrupados[ano] = {
                    ano: ano,
                    resultado: 0,
                    resultadoFormatado: ''
                };
            }
            dadosAgrupados[ano].resultado += resultado;
            dadosAgrupados[ano].resultadoFormatado = formatarNumero(dadosAgrupados[ano].resultado);
        }
    }

    var listaDados = [];
    for (var key in dadosAgrupados) {
        listaDados.push(dadosAgrupados[key]);
    }

    listaDados.sort(function(a, b) {
        return a.ano.localeCompare(b.ano);
    });

    data.dadosGraficoLinha = listaDados;
})();
